{"name": "create_monthly_sales_summary", "query": "
-- ============================================================
-- Table 1: Monthly Sales Summary
-- Tracks financial & customer KPIs per calendar month
-- ============================================================
CREATE TABLE IF NOT EXISTS public.monthly_sales_summary (
    year_month            VARCHAR(7)      NOT NULL,   -- 'YYYY-MM'
    total_invoices        INTEGER         NOT NULL,
    total_revenue         DECIMAL(10, 2)  NOT NULL,
    total_tracks_sold     INTEGER         NOT NULL,
    average_invoice_value DECIMAL(10, 2)  NOT NULL,
    unique_customers      INTEGER         NOT NULL,
    CONSTRAINT pk_monthly_sales_summary PRIMARY KEY (year_month),
    CONSTRAINT chk_year_month_format    CHECK (year_month ~ '^\d{4}-\d{2}$'),
    CONSTRAINT chk_total_invoices       CHECK (total_invoices        > 0),
    CONSTRAINT chk_total_revenue        CHECK (total_revenue         >= 0),
    CONSTRAINT chk_total_tracks_sold    CHECK (total_tracks_sold     >= 0),
    CONSTRAINT chk_average_invoice      CHECK (average_invoice_value >= 0),
    CONSTRAINT chk_unique_customers     CHECK (unique_customers      > 0)
);

COMMENT ON TABLE  public.monthly_sales_summary                        IS 'Monthly aggregated sales KPIs derived from Chinook Invoice & InvoiceLine data.';
COMMENT ON COLUMN public.monthly_sales_summary.year_month             IS 'Calendar month in YYYY-MM format (primary key).';
COMMENT ON COLUMN public.monthly_sales_summary.total_invoices         IS 'Count of invoices issued in the month.';
COMMENT ON COLUMN public.monthly_sales_summary.total_revenue          IS 'Sum of all invoice totals for the month.';
COMMENT ON COLUMN public.monthly_sales_summary.total_tracks_sold      IS 'Total quantity of individual track lines sold in the month.';
COMMENT ON COLUMN public.monthly_sales_summary.average_invoice_value  IS 'Mean invoice value for the month (total_revenue / total_invoices).';
COMMENT ON COLUMN public.monthly_sales_summary.unique_customers        IS 'Count of distinct customers who placed at least one order in the month.';
"}

{"name": "create_top_music_charts", "query": "
-- ============================================================
-- Table 2: Top Music Charts
-- Stores pre-ranked Top-10 charts for tracks, albums & artists
-- ============================================================
CREATE TABLE IF NOT EXISTS public.top_music_charts (
    chart_type     VARCHAR(20)    NOT NULL,  -- 'top_tracks' | 'top_albums' | 'top_artists'
    rank_position  INTEGER        NOT NULL,  -- 1-10
    item_id        INTEGER        NOT NULL,
    item_name      VARCHAR(255)   NOT NULL,
    total_revenue  DECIMAL(10, 2) NOT NULL,
    CONSTRAINT pk_top_music_charts       PRIMARY KEY (chart_type, rank_position),
    CONSTRAINT chk_chart_type            CHECK (chart_type IN ('top_tracks', 'top_albums', 'top_artists')),
    CONSTRAINT chk_rank_position         CHECK (rank_position BETWEEN 1 AND 10),
    CONSTRAINT chk_chart_total_revenue   CHECK (total_revenue > 0)
);

COMMENT ON TABLE  public.top_music_charts                IS 'All-time Top-10 charts for tracks, albums, and artists ranked by revenue / quantity sold.';
COMMENT ON COLUMN public.top_music_charts.chart_type     IS 'Chart category: top_tracks, top_albums, or top_artists.';
COMMENT ON COLUMN public.top_music_charts.rank_position  IS 'Ranking position within the chart (1 = best performer).';
COMMENT ON COLUMN public.top_music_charts.item_id        IS 'Primary key of the ranked entity (TrackId, AlbumId, or ArtistId).';
COMMENT ON COLUMN public.top_music_charts.item_name      IS 'Display name of the ranked entity.';
COMMENT ON COLUMN public.top_music_charts.total_revenue  IS 'Total revenue generated by this entity across all time.';
"}

